# Dotstory - content v2 update (new copy from content document, readable font, bigger text, hero CTA removed)
# Usage: powershell -ExecutionPolicy Bypass -File .\apply-dotstory-content-v2.ps1 [-SiteFolder <path>] [-SiteUrl https://dotstory.io] [-Push]
param([string]$SiteFolder=(Get-Location).Path,[string]$SiteUrl='https://dotstory.io',[switch]$Push)
$ErrorActionPreference='Stop'
$SiteUrl=$SiteUrl.TrimEnd('/')
if(-not((Test-Path (Join-Path $SiteFolder 'index.html')) -and (Test-Path (Join-Path $SiteFolder '_nuxt')))){throw "Run this inside your site folder (index.html + _nuxt), or pass -SiteFolder."}
$files=@(
  @{Path='404.html';Sha='4020abfe97ce24d6c71ddac0b7c5f46b91f0bc470725d7bfa6740c12cd700d02';Data=''},
  @{Path='_nuxt/BAugoq4T.js';Sha='1cdc39fbb0fbcf989d095bfc2247d1a5143d0866bcf6733ff35c81253f4dc10c';Data=''},
  @{Path='_nuxt/CPjIKiRm.js';Sha='b5e34941fa3effd6d678297af8988dc54483ffb6011f1dcaa5b58cb348838d91';Data=''},
  @{Path='_nuxt/DC_P54Ec.js';Sha='cb9a9f5c035b35c634bdaea2e196d5d164508788a9c3761fa87ba1b22f2a90f3';Data=''},
  @{Path='_nuxt/DtFrKc8W.js';Sha='bffcbb86ab24345f53e726ef01947ed41b3b145747f36953582025559f3fe7aa';Data=''},
  @{Path='_nuxt/t9sCvZVC.js';Sha='900d53195d6ab5bade7f4817cc1099a38b8f676db1972a47e0d40f5a21b668a9';Data=''},
  @{Path='about';Sha='47f6c3116b32f3ec869d4eeb126c6c27a7af9dace086b86beb969d2d8e37cda8';Data=''},
  @{Path='contact';Sha='0bb033e3d007329f87f61e8f2dd4efeb3b39f6a9dd5ed13e495f13de996ed6c9';Data=''},
  @{Path='favicon.svg';Sha='4824a2fb761e641622f0f3e9c403a633111d6c6cef9d589fbe519beab774d6a8';Data='H4sIAPeJ8GoC/z3N2wrCMAwG4HufIsT7td1EQdpe+Caj9gTVSVeW+fbLHBgCf0g+iJ6XCOurvGeDqbXPXQgi6mjophpFL6UULBCW7OkxrQYlSLheuNHq6l0Dys+WDPICks8xtWOubBVnyKUYPKugRnVDYbXL1RUPju9Dj+C+R1bm6s/Dr3a+v7enDYBHJgKnAAAA'},
  @{Path='index.html';Sha='81743ee4a9390930401ad5d5a7912eb46c7e52e6d5e0bfc32edf772b6158d437';Data=''},
  @{Path='legal';Sha='965e35ed4447bd61cf78e09a61f5c7101fb38f2d4f3a9728c8e92fd734a026b9';Data=''},
  @{Path='llms.txt';Sha='ee11b72a1377edaafdf353e75a2392fdb69ce3d2a078c38a48778ea320176b42';Data=''},
  @{Path='robots.txt';Sha='b2b96f00615b081b22ea7500bb26986e986cf122633ffbefbb18c28f6297af5d';Data='H4sIAPeJ8GoC/4WPywqDMBBF9/mKge4KqXt3tpTiqoK6DkOcamBMJEmr/fs+dCGFtquBcw/3MnUgL7ElG1PYiozZjSkkQmwgywFtGMkD2dZYCiBBexwZLs4DmxsteXjeBrSJGI2zQdSrynOWy5LQ627v4qp+7Rw6jKeiki/2RSnID0yTifcfNYzXhv6vzdrH2AZKE6nHAdjp9x9iASkoVebVUakkzGQ39SweTSL+rDgBAAA='},
  @{Path='services';Sha='ee85479e1cb4cd8725f34bec42bf98ff1fd2bf836ebe680a1c95a2df4fcba0c3';Data=''},
  @{Path='sitemap.xml';Sha='38340f0268e1a21e25426fccba7023122e48940b4562511b2f016c8f24a00f56';Data='H4sIAPeJ8GoC/62RPQ+CMBCGd35F0x0OGPwKlEkTZ3EmWBppAi3pFdB/b1Hi5gBxunvv67nLJdmjbcggDEqtUhoFISVCcV1JdU/pNT/5O5oxL+lNg8ISV6wwpbW13QFgHMcApRVt2WGgzR2Q104gzEEIgz1lHiFT+2Sd12jOiuJyzo9FAQlMck6UaFtdsTiMN34U+WHksnPsU9EZqY20T+a2TOCrpvkwA36BUJhBcoErge6OhcDypnu7mrZdSONa2ZL/m/c27uvMewGES8FFJgIAAA=='},
  @{Path='vercel.json';Sha='73ba366a2408184bd3c293c3a4b6edade23526df0cb90d9ad3919d20bddbf745';Data=''}
)
$stamp=Get-Date -Format 'yyyyMMdd_HHmmss'
$bk=Join-Path $SiteFolder ('_backup_before_content_v2_'+$stamp)
New-Item -ItemType Directory -Path $bk | Out-Null
$textExt=@('.html','.txt','.xml','.json','.svg')
$textNames=@('about','services','contact','legal')
$enc=New-Object System.Text.UTF8Encoding($false)
foreach($f in $files){
  $bytes=[Convert]::FromBase64String($f.Data)
  $ms=New-Object System.IO.MemoryStream(,$bytes)
  $gz=New-Object System.IO.Compression.GZipStream($ms,[System.IO.Compression.CompressionMode]::Decompress)
  $out=New-Object System.IO.MemoryStream
  $gz.CopyTo($out);$raw=$out.ToArray()
  $sha=[BitConverter]::ToString([Security.Cryptography.SHA256]::Create().ComputeHash($raw)).Replace('-','').ToLower()
  if($sha -ne $f.Sha){throw "Checksum failed for $($f.Path)"}
  $dest=Join-Path $SiteFolder $f.Path
  $dir=Split-Path $dest -Parent
  if(-not(Test-Path $dir)){New-Item -ItemType Directory -Path $dir | Out-Null}
  if(Test-Path $dest){$bd=Join-Path $bk $f.Path;$bdd=Split-Path $bd -Parent;if(-not(Test-Path $bdd)){New-Item -ItemType Directory -Path $bdd | Out-Null};Copy-Item $dest $bd}
  $ext=[IO.Path]::GetExtension($f.Path).ToLower()
  if(($textExt -contains $ext) -or ($textNames -contains $f.Path)){
    $t=$enc.GetString($raw).Replace('__SITE__',$SiteUrl)
    [IO.File]::WriteAllBytes($dest,$enc.GetBytes($t))
  } else {[IO.File]::WriteAllBytes($dest,$raw)}
  Write-Host ("updated  "+$f.Path)
}
Write-Host ""
Write-Host "Done. Backup of replaced files: $bk"
if($Push){
  Push-Location $SiteFolder
  git add -A -- . ':!_backup_before_*'
  git commit -m "Update site content, readable font and larger text"
  git push
  Pop-Location
} else {Write-Host "Preview locally, then deploy (or re-run with -Push to git push)."}
